const e=JSON.parse(`[{"id":"t1","title":"模拟听力 1","sections":[{"n":1,"title":"Booking a holiday cottage","intro":"Section 1. You will hear a woman phoning a holiday letting agency to book a cottage.","speakers":{"A":{"voice":"Karen","name":"Agent"},"B":{"voice":"Moira","name":"Caller"}},"groups":[{"title":"Questions 1–10","instruction":"Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","questions":[{"n":1,"type":"gap","q":"Cottage booked: ______ House","answer":["Seagull"],"line":6},{"n":2,"type":"gap","q":"Arrival date: ______ August","answer":["12","12th","twelfth"],"line":5},{"n":3,"type":"gap","q":"Advantage of this cottage: a larger ______","answer":["garden"],"line":8},{"n":4,"type":"gap","q":"Surname: ______","answer":["Pendleton"],"line":11},{"n":5,"type":"gap","q":"Number of children: ______","answer":["3","three"],"line":13},{"n":6,"type":"gap","q":"Extra charge for the dog: £______","answer":["15","fifteen"],"line":16},{"n":7,"type":"gap","q":"Parking: free car park behind the ______","answer":["church"],"line":20},{"n":8,"type":"gap","q":"Check-in from: ______ o'clock","answer":["4","four"],"line":13},{"n":9,"type":"gap","q":"Guests must bring their own ______","answer":["towels"],"line":24},{"n":10,"type":"gap","q":"Deposit: £______","answer":["100","one hundred"],"line":26}]}],"audio":"t1-s1.mp3","duration":162,"lines":[{"who":"A","text":"Good afternoon, Coastline Cottages. This is Fiona speaking. How can I help?","start":7.26,"end":13.63},{"who":"B","text":"Hello. I'd like to book one of your cottages for a week in the summer, if you still have anything available.","start":14.23,"end":20.86},{"who":"A","text":"Certainly. Which cottage were you interested in?","start":21.46,"end":24.84},{"who":"B","text":"The one called Harbour View. I saw it on your website.","start":25.44,"end":29.62},{"who":"A","text":"Ah yes, that's a lovely one. What dates were you thinking of?","start":30.22,"end":34.36},{"who":"B","text":"We'd like to arrive on the twelfth of August and stay for seven nights.","start":34.96,"end":38.93},{"who":"A","text":"Let me check. Hmm, I'm afraid Harbour View is already booked that week. But we have a very similar cottage called Seagull House, just two streets away. It also sleeps six people.","start":39.53,"end":52.4},{"who":"B","text":"Oh, that's a pity. Is Seagull House close to the beach as well?","start":53,"end":57.61},{"who":"A","text":"Yes, it's about a five-minute walk. It doesn't have a sea view, but it has a larger garden.","start":58.21,"end":64.21},{"who":"B","text":"Well, a garden would be nice for the children. Let's book Seagull House, then.","start":64.81,"end":70.41},{"who":"A","text":"Great. Can I take your name, please?","start":71.01,"end":74.03},{"who":"B","text":"Yes, it's Rachel Pendleton. That's P-E-N-D-L-E-T-O-N.","start":74.63,"end":79.81},{"who":"A","text":"Thank you. And a phone number?","start":80.41,"end":82.77},{"who":"B","text":"My mobile is 07832 559 104.","start":83.37,"end":88.55},{"who":"A","text":"Lovely. How many people will be staying?","start":89.15,"end":92.22},{"who":"B","text":"Two adults and three children. Oh, and we'd like to bring our dog. Is that allowed?","start":92.82,"end":99.66},{"who":"A","text":"Yes, Seagull House accepts one dog, but there's an extra charge of fifteen pounds for cleaning.","start":100.26,"end":105.93},{"who":"B","text":"That's fine. And what's the total price for the week?","start":106.53,"end":110.3},{"who":"A","text":"In August it's six hundred and forty pounds, plus the fifteen pounds for the dog.","start":110.9,"end":115.46},{"who":"B","text":"OK. Is there anywhere to park?","start":116.06,"end":119.04},{"who":"A","text":"There's no parking at the cottage itself, but guests can use the car park behind the church, and it's free.","start":119.64,"end":125.54},{"who":"B","text":"Good. And what time can we get the keys?","start":126.14,"end":129.4},{"who":"A","text":"Check-in is from four o'clock. The keys will be in a box by the front door, and we'll text you the code the day before.","start":130,"end":137.07},{"who":"B","text":"Perfect. Is there anything we need to bring?","start":137.67,"end":140.95},{"who":"A","text":"Bedding is provided, but you'll need to bring your own towels. And there's no dishwasher, I'm afraid.","start":141.55,"end":148.01},{"who":"B","text":"Towels, right. How do I pay?","start":148.61,"end":151.8},{"who":"A","text":"We take a deposit of one hundred pounds now, and the rest four weeks before you arrive.","start":152.4,"end":157.22},{"who":"B","text":"Fine. I'll pay the deposit by card.","start":157.82,"end":160.99}],"testId":"t1"},{"n":2,"title":"Volunteering at the city museum","intro":"Section 2. You will hear the volunteer coordinator at a city museum speaking to a group of new volunteers.","speakers":{"A":{"voice":"Daniel","name":"Coordinator"}},"groups":[{"title":"Questions 11–15","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":11,"type":"mcq","q":"Volunteers should enter the museum","options":["A  through the main door.","B  through the staff entrance on Mill Lane.","C  through the café entrance."],"answer":"B","key":"staff entrance, which is on Mill Lane","explain":"明确说用 Mill Lane 的员工入口，不要走广场上的正门。","line":2},{"n":12,"type":"mcq","q":"How often must new volunteers work?","options":["A  at least once a week","B  at least once every two weeks","C  at least once a month"],"answer":"B","key":"at least one shift a fortnight","explain":"a fortnight 就是两周（every two weeks）。once a week 是很多人自愿的频率，是干扰项。","line":4},{"n":13,"type":"mcq","q":"What do volunteers need in order to use a locker?","options":["A  a one pound coin","B  their badge","C  a key from security"],"answer":"A","key":"you'll need a one pound coin","explain":"储物柜免费，但要一枚 1 镑硬币，开柜时退还。","line":5},{"n":14,"type":"mcq","q":"Volunteers get a discount in","options":["A  the gift shop only.","B  the café only.","C  both the café and the gift shop."],"answer":"B","key":"doesn't include the gift shop","explain":"咖啡馆打七折，但 that doesn't include the gift shop，所以只有咖啡馆。","line":6},{"n":15,"type":"mcq","q":"What is the main job of a gallery assistant?","options":["A  photographing new objects","B  running workshops for children","C  helping visitors and protecting the objects"],"answer":"C","key":"answer visitors' questions and make sure people don't touch the objects","explain":"A 是幕后志愿者的工作，B 是有带孩子经验的人做的，展厅助理的主要工作是 C。","line":7}]},{"title":"Questions 16–20","instruction":"Label the plan of the museum. Choose the correct letter, A–G, for each place. Plan: the entrance hall is at the front; A is on the left of the entrance, B on the right, C straight ahead, D at the back overlooking the garden, E upstairs next to the textiles gallery, F beside the lifts, G opposite the lifts.","box":["A  left of the entrance","B  right of the entrance","C  straight ahead of the entrance","D  at the back, overlooking the garden","E  upstairs, next to the textiles gallery","F  beside the lifts","G  opposite the lifts"],"questions":[{"n":16,"type":"match","q":"Roman gallery","options":["A","B","C","D","E","F","G"],"answer":"A","key":"large room on your left as you come in","line":11},{"n":17,"type":"match","q":"Natural History room","options":["A","B","C","D","E","F","G"],"answer":"B","key":"room to the right of the entrance","line":12},{"n":18,"type":"match","q":"Café","options":["A","B","C","D","E","F","G"],"answer":"D","key":"at the back of the building, overlooking the garden","line":13},{"n":19,"type":"match","q":"Education room","options":["A","B","C","D","E","F","G"],"answer":"E","key":"next to the textiles gallery","line":14},{"n":20,"type":"match","q":"First aid room","options":["A","B","C","D","E","F","G"],"answer":"F","key":"beside the lifts, opposite the cloakroom","explain":"first aid room 在电梯旁边（F）；opposite 说的是衣帽间在它对面，别选成 G。","line":15}]}],"audio":"t1-s2.mp3","duration":134,"lines":[{"who":"A","text":"Good morning, everyone, and welcome to the Westbridge City Museum. My name is Tom Ashby, and I coordinate our volunteer programme.","start":8.67,"end":16.74},{"who":"A","text":"We now have over eighty volunteers, and to be honest, the museum couldn't open seven days a week without you.","start":17.19,"end":23.21},{"who":"A","text":"Let me start with some practical information. Volunteers should always use the staff entrance, which is on Mill Lane, not the main door on the square.","start":23.66,"end":31.92},{"who":"A","text":"When you arrive, please sign in at the security desk. You'll be given a badge, and you must wear it at all times while you're in the building.","start":32.37,"end":39.81},{"who":"A","text":"Each shift lasts four hours. We ask new volunteers to do at least one shift a fortnight, although many people come in every week.","start":40.26,"end":48.14},{"who":"A","text":"Lockers are available in the basement for your bags and coats. They're free, but you'll need a one pound coin, which you get back when you open the locker again.","start":48.59,"end":56.83},{"who":"A","text":"Now, a lot of you have asked about refreshments. Volunteers get a thirty percent discount in the café on the ground floor. Unfortunately, that doesn't include the gift shop.","start":57.28,"end":68.09},{"who":"A","text":"Let me tell you about the different roles. Most of you will start as gallery assistants. Your main job is to answer visitors' questions and make sure people don't touch the objects.","start":68.54,"end":78.89},{"who":"A","text":"Some of you have experience with children, so you may help with the family workshops on Saturday mornings.","start":79.34,"end":84.51},{"who":"A","text":"And finally, a few volunteers work behind the scenes, helping our curators to record and photograph new items for the collection.","start":84.96,"end":92.18},{"who":"A","text":"Now, let's look at the map of the building, so you know where things are.","start":92.63,"end":96.1},{"who":"A","text":"We're standing in the entrance hall. Straight ahead of you is the main staircase. The Roman gallery is the large room on your left as you come in.","start":96.55,"end":105.24},{"who":"A","text":"The room to the right of the entrance is the Natural History room, with the famous dinosaur skeleton.","start":105.69,"end":110.27},{"who":"A","text":"Go past the staircase and you'll come to the café, at the back of the building, overlooking the garden.","start":110.72,"end":115.69},{"who":"A","text":"The education room, where the family workshops take place, is upstairs, next to the textiles gallery.","start":116.14,"end":122.11},{"who":"A","text":"And the first aid room is beside the lifts, opposite the cloakroom. If anyone feels unwell, take them there and call security.","start":122.56,"end":130.13},{"who":"A","text":"Right, any questions before we start the tour?","start":130.58,"end":133.01}],"testId":"t1"},{"n":3,"title":"A research project on community gardens","intro":"Section 3. You will hear two students, Maya and Leo, talking to their tutor, Dr Grant, about their research project on community gardens.","speakers":{"A":{"voice":"Samantha","name":"Maya"},"B":{"voice":"Rishi","name":"Leo"},"C":{"voice":"Tessa","name":"Dr Grant"}},"groups":[{"title":"Questions 21–25","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":21,"type":"mcq","q":"Why did the students change their original topic?","options":["A  It was too broad.","B  Their tutor rejected it.","C  There was not enough information."],"answer":"A","key":"we found that was too broad","line":3},{"n":22,"type":"mcq","q":"According to the interviews, the main benefit of community gardens is","options":["A  saving money on food.","B  meeting other people.","C  eating healthy vegetables."],"answer":"B","key":"the main benefit was meeting their neighbours","explain":"meeting their neighbours ≈ meeting other people。saving money 是学生原来以为的，只有少数人提到。","line":6},{"n":23,"type":"mcq","q":"What was the biggest problem when collecting data?","options":["A  People refused to be interviewed.","B  The weather was bad.","C  The recording equipment failed."],"answer":"B","key":"The biggest problem was the weather","explain":"有些老人不愿被录音，但最大的问题是天气。","line":9},{"n":24,"type":"mcq","q":"What will the students do next?","options":["A  visit more gardens","B  interview older people again","C  send an online questionnaire"],"answer":"C","key":"send an online questionnaire","line":12},{"n":25,"type":"mcq","q":"How many questions does the tutor recommend?","options":["A  no more than ten","B  about twenty","C  as many as possible"],"answer":"A","key":"Ten questions at the most","explain":"at the most = no more than。twenty 是学生原来的打算。","line":13}]},{"title":"Questions 26–29","instruction":"What is special about each garden? Choose FOUR answers from the box and write the correct letter, A–F.","box":["A  It receives money from a company.","B  It is used mainly by new arrivals to the city.","C  It is the largest garden.","D  It was built on an old car park.","E  It is run by young people.","F  It sells vegetables at a market."],"questions":[{"n":26,"type":"match","q":"Elm Street","options":["A","B","C","D","E","F"],"answer":"E","key":"run entirely by teenagers","line":16},{"n":27,"type":"match","q":"Riverside","options":["A","B","C","D","E","F"],"answer":"D","key":"land that used to be a car park","line":17},{"n":28,"type":"match","q":"Hilltop","options":["A","B","C","D","E","F"],"answer":"A","key":"The company pays for tools and seeds","line":18},{"n":29,"type":"match","q":"Brook Lane","options":["A","B","C","D","E","F"],"answer":"B","key":"recently moved to the city from other countries","line":19}]},{"title":"Question 30","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":30,"type":"mcq","q":"What does the tutor think will make the report stronger?","options":["A  the number of interviews","B  the variety of gardens","C  the use of photographs"],"answer":"B","key":"That variety will make your report much stronger","line":20}]}],"audio":"t1-s3.mp3","duration":158.6,"lines":[{"who":"C","text":"So, Maya and Leo, how is the community garden project going?","start":11.48,"end":15.77},{"who":"A","text":"Quite well, I think. We've visited four gardens in the city so far, and we've interviewed about thirty people who use them.","start":16.37,"end":23.91},{"who":"C","text":"Good. Why did you choose this topic in the first place?","start":24.51,"end":28.35},{"who":"B","text":"Well, at first we wanted to look at food prices, but we found that was too broad. Then Maya read an article about how gardening affects people's mental health, and that seemed more interesting.","start":28.95,"end":43},{"who":"A","text":"Yes, and it's something we could actually measure, through interviews.","start":43.6,"end":47.13},{"who":"C","text":"And what have you found so far?","start":47.73,"end":49.31},{"who":"B","text":"The most surprising thing was that most people didn't mention the vegetables at all. They said the main benefit was meeting their neighbours.","start":49.91,"end":59.54},{"who":"A","text":"Exactly. We expected them to talk about saving money, but only a few people did.","start":60.14,"end":65.7},{"who":"C","text":"That's interesting. Did you have any problems collecting the data?","start":66.3,"end":70.59},{"who":"B","text":"The biggest problem was the weather. It rained on three of our visits, so there were hardly any people in the gardens.","start":71.19,"end":79.66},{"who":"A","text":"We also found that some older people didn't want to be recorded, so we had to take notes by hand instead.","start":80.26,"end":85.42},{"who":"C","text":"That's quite common. Now, what are you planning to do next?","start":86.02,"end":90.4},{"who":"A","text":"We'd like to send an online questionnaire to all the garden members, so we get more responses.","start":91,"end":95.89},{"who":"C","text":"That's a good idea, but keep it short. Ten questions at the most, or people won't finish it.","start":96.49,"end":103.26},{"who":"B","text":"OK. We were going to have twenty, so we'll cut it down.","start":103.86,"end":108.57},{"who":"C","text":"Now, let's talk about the four gardens you visited. Can you tell me what was special about each one?","start":109.17,"end":115.37},{"who":"A","text":"Sure. The garden on Elm Street is run entirely by teenagers from the local school. They grow vegetables for the school kitchen.","start":115.97,"end":124.2},{"who":"B","text":"Then there's Riverside Garden, which is the oldest one. It was started in the nineteen seventies on land that used to be a car park.","start":124.8,"end":134.68},{"who":"A","text":"Hilltop Garden is the one that gets money from a supermarket. The company pays for tools and seeds.","start":135.28,"end":141.23},{"who":"B","text":"And the last one, Brook Lane, is mainly used by people who have recently moved to the city from other countries. They grow plants from their home countries.","start":141.83,"end":152.81},{"who":"C","text":"Very good. That variety will make your report much stronger.","start":153.41,"end":157.61}],"testId":"t1"},{"n":4,"title":"The history of the bicycle","intro":"Section 4. You will hear part of a lecture about the history of the bicycle.","speakers":{"A":{"voice":"Moira","name":"Lecturer"}},"groups":[{"title":"Questions 31–40","instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","questions":[{"n":31,"type":"gap","q":"Early bicycle (1817): invented in ______","answer":["Germany"],"line":1},{"n":32,"type":"gap","q":"It had no ______, so riders pushed with their feet","answer":["pedals"],"line":1},{"n":33,"type":"gap","q":"It was made mostly of ______","answer":["wood"],"line":2},{"n":34,"type":"gap","q":"Possible reason for invention: horses were expensive to ______","answer":["feed"],"line":3},{"n":35,"type":"gap","q":"1860s 'boneshaker': journeys were rough because of the ______ tyres","answer":["iron"],"line":4},{"n":36,"type":"gap","q":"Safety bicycle (1880s): a ______ connected the pedals to the back wheel","answer":["chain"],"line":6},{"n":37,"type":"gap","q":"Social effects: workers could travel further to find a ______","answer":["job"],"line":8},{"n":38,"type":"gap","q":"Women gained more ______","answer":["independence"],"line":9},{"n":39,"type":"gap","q":"Today: the key factor in encouraging cycling is ______","answer":["safety"],"line":6},{"n":40,"type":"gap","q":"Electric bikes are popular with older riders because they make ______ easier","answer":["hills"],"line":13}]}],"audio":"t1-s4.mp3","duration":149.4,"lines":[{"who":"A","text":"Today I'm going to talk about the history of the bicycle, a machine that has changed far more than just the way we travel.","start":6.59,"end":13.31},{"who":"A","text":"The first machine that we would recognise as a bicycle was invented in Germany in eighteen seventeen. It had two wheels, but no pedals, and the rider pushed it along with their feet.","start":13.76,"end":25.41},{"who":"A","text":"It was made almost entirely of wood, so it was heavy and very uncomfortable to ride.","start":25.86,"end":31.09},{"who":"A","text":"Interestingly, one reason for its invention may have been the weather. A volcanic eruption had caused crop failures, and horses were expensive to feed, so people needed another way to travel.","start":31.54,"end":43.76},{"who":"A","text":"In the eighteen sixties, pedals were added to the front wheel. These bicycles were nicknamed boneshakers, because the iron tyres made every journey extremely rough.","start":44.21,"end":54.92},{"who":"A","text":"Then came the high-wheeler, with an enormous front wheel. A larger wheel meant the bicycle could go faster, but riders often fell forward over the handlebars, so it was mainly popular with young men who wanted excitement.","start":55.37,"end":69.59},{"who":"A","text":"The real breakthrough was the so-called safety bicycle of the eighteen eighties. Its two wheels were the same size, and a chain connected the pedals to the back wheel.","start":70.04,"end":80.39},{"who":"A","text":"Soon afterwards, air-filled rubber tyres were introduced, which made cycling far more comfortable.","start":80.84,"end":86.65},{"who":"A","text":"The safety bicycle had important social effects. For the first time, ordinary working people could travel several miles to find a job, without needing a horse or a train ticket.","start":87.1,"end":99.22},{"who":"A","text":"It also gave women much greater independence. Many women started wearing shorter skirts and even trousers so that they could ride.","start":99.67,"end":108.34},{"who":"A","text":"In the twentieth century, however, the car became the main form of private transport in most Western countries, and cycling declined.","start":108.79,"end":117.04},{"who":"A","text":"Today, cycling is growing again, mainly because of concerns about pollution and health. Cities such as Copenhagen have built networks of separate cycle lanes.","start":117.49,"end":128.37},{"who":"A","text":"Research suggests that the most important factor in persuading people to cycle is not money, but safety. People need to feel protected from traffic.","start":128.82,"end":138.26},{"who":"A","text":"Finally, electric bicycles are now one of the fastest-growing areas of the market, especially among older riders, because they make hills much easier to climb.","start":138.71,"end":148.41}],"testId":"t1"}]},{"id":"t2","title":"模拟听力 2","sections":[{"n":1,"title":"Joining the public library","intro":"Section 1. You will hear a man joining a public library.","speakers":{"A":{"voice":"Tessa","name":"Librarian"},"B":{"voice":"Daniel","name":"Man"}},"groups":[{"title":"Questions 1–10","instruction":"Complete the form below. Write ONE WORD AND/OR A NUMBER for each answer.","questions":[{"n":1,"type":"gap","q":"Surname: ______","answer":["Okafor"],"line":3},{"n":2,"type":"gap","q":"Address: Flat 3, 42 ______ Road","answer":["Lindsay"],"line":5},{"n":3,"type":"gap","q":"Proof of address: ______ agreement","answer":["tenancy"],"line":11},{"n":4,"type":"gap","q":"Date of birth: ______ March 1991","answer":["9","9th","ninth"],"line":13},{"n":5,"type":"gap","q":"Maximum items at one time: ______","answer":["12","twelve"],"line":16},{"n":6,"type":"gap","q":"Late fee for DVDs: ______p per day","answer":["20","twenty"],"line":18},{"n":7,"type":"gap","q":"Free computer use: ______ hour(s) a day","answer":["1","one"],"line":13},{"n":8,"type":"gap","q":"Study room: on the ______ floor","answer":["second","2nd"],"line":22},{"n":9,"type":"gap","q":"Saturday closing time: ______ pm","answer":["5","five"],"line":24},{"n":10,"type":"gap","q":"Book club: last ______ of every month","answer":["Wednesday"],"line":26}]}],"audio":"t2-s1.mp3","duration":137.8,"lines":[{"who":"A","text":"Hello, can I help you?","start":5.67,"end":7.32},{"who":"B","text":"Yes, I've just moved to the area and I'd like to join the library.","start":7.92,"end":11.33},{"who":"A","text":"Of course. I just need to take a few details. What's your full name?","start":11.93,"end":17.57},{"who":"B","text":"It's Martin Okafor. That's O-K-A-F-O-R.","start":18.17,"end":21.61},{"who":"A","text":"Thank you. And your address?","start":22.21,"end":24.64},{"who":"B","text":"Flat three, forty-two Lindsay Road.","start":25.24,"end":27.7},{"who":"A","text":"Is that Lindsay with an A-Y at the end?","start":28.3,"end":30.51},{"who":"B","text":"Yes, that's right. L-I-N-D-S-A-Y.","start":31.11,"end":34.86},{"who":"A","text":"And the postcode?","start":35.46,"end":36.36},{"who":"B","text":"It's BR7 4QN.","start":36.96,"end":39},{"who":"A","text":"Thanks. Do you have something with your address on it? A bill or a bank letter?","start":39.6,"end":45.48},{"who":"B","text":"I've got my tenancy agreement here. Will that do?","start":46.08,"end":49.45},{"who":"A","text":"That's fine. And what's your date of birth?","start":50.05,"end":52.92},{"who":"B","text":"The ninth of March, nineteen ninety-one.","start":53.52,"end":55.81},{"who":"A","text":"Lovely. Now, how many books can I borrow at once? That's usually the first question people ask.","start":56.41,"end":64.12},{"who":"B","text":"Ha, yes, I was going to ask that.","start":64.72,"end":67.09},{"who":"A","text":"You can borrow up to twelve items at a time, for three weeks. And you can renew them online, as long as nobody else has reserved them.","start":67.69,"end":76.47},{"who":"B","text":"What happens if I return something late?","start":77.07,"end":78.93},{"who":"A","text":"There are no fines for books any more, but DVDs are twenty pence a day.","start":79.53,"end":83.79},{"who":"B","text":"OK. Do you have computers I can use? My laptop is still in a box somewhere.","start":84.39,"end":90.46},{"who":"A","text":"Yes, members get one hour of free computer use every day. You just book a time at the desk upstairs.","start":91.06,"end":98.23},{"who":"B","text":"Great. And is there anywhere quiet to study?","start":98.83,"end":101.93},{"who":"A","text":"The study room is on the second floor. It's open until eight in the evening from Monday to Thursday.","start":102.53,"end":108.52},{"who":"B","text":"And at weekends?","start":109.12,"end":109.97},{"who":"A","text":"On Saturday we close at five, and we're closed on Sundays.","start":110.57,"end":114.22},{"who":"B","text":"I saw a poster about a book club. How do I join that?","start":114.82,"end":118.55},{"who":"A","text":"It meets on the last Wednesday of every month. Just send an email to Karen, who organises it. Her address is on the poster.","start":119.15,"end":128.17},{"who":"B","text":"Thanks. Oh, and can I get the library newsletter?","start":128.77,"end":132.27},{"who":"A","text":"Certainly. I'll tick the box so it comes to your email.","start":132.87,"end":136.79}],"testId":"t2"},{"n":2,"title":"The Harbour Food Festival","intro":"Section 2. You will hear a radio presenter talking about a local food festival.","speakers":{"A":{"voice":"Samantha","name":"Presenter"}},"groups":[{"title":"Questions 11–15","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":11,"type":"mcq","q":"How many stalls will there be this year?","options":["A  12","B  about 100","C  over 150"],"answer":"C","key":"more than one hundred and fifty","line":1},{"n":12,"type":"mcq","q":"Why is entry free this year?","options":["A  It is the festival's tenth year.","B  A bank is sponsoring the event.","C  The council has paid for it."],"answer":"B","key":"a local bank has agreed to sponsor the event","line":2},{"n":13,"type":"mcq","q":"What does the presenter advise visitors to do?","options":["A  arrive by car early","B  use the shuttle bus","C  walk from the station"],"answer":"B","key":"take the free shuttle bus from the railway station","line":3},{"n":14,"type":"mcq","q":"What is new at this year's festival?","options":["A  There are no plastic plates or cups.","B  There is a children's cookery school.","C  There are cooking demonstrations."],"answer":"A","key":"there will be no plastic plates or cups","line":10},{"n":15,"type":"mcq","q":"When must cake competition entries be delivered?","options":["A  by 11 am on Saturday","B  by 4 pm on Saturday","C  by 11 am on Sunday"],"answer":"A","key":"by eleven o'clock on Saturday morning","explain":"four o'clock 是公布获奖者的时间，不是交作品的时间。","line":11}]},{"title":"Questions 16–20","instruction":"What can visitors find in each area? Choose FIVE answers from the box and write the correct letter, A–G.","box":["A  international food","B  live music","C  cooking demonstrations","D  wine tasting","E  activities for children","F  local produce","G  a cake competition"],"questions":[{"n":16,"type":"match","q":"Market Square","options":["A","B","C","D","E","F","G"],"answer":"F","key":"local farmers will be selling fresh fruit, vegetables and cheese","line":5},{"n":17,"type":"match","q":"Fish Quay","options":["A","B","C","D","E","F","G"],"answer":"C","key":"giving cooking demonstrations every hour","line":6},{"n":18,"type":"match","q":"Old Warehouse","options":["A","B","C","D","E","F","G"],"answer":"A","key":"food from around the world","line":7},{"n":19,"type":"match","q":"Castle Gardens","options":["A","B","C","D","E","F","G"],"answer":"E","key":"games and a children's cookery school","line":8},{"n":20,"type":"match","q":"Lighthouse Lawn","options":["A","B","C","D","E","F","G"],"answer":"B","key":"live acoustic music","line":9}]}],"audio":"t2-s2.mp3","duration":111.8,"lines":[{"who":"A","text":"And now for some good news for food lovers. The Harbour Food Festival returns this weekend for its tenth year.","start":7.16,"end":13.51},{"who":"A","text":"The festival started as a small market with just twelve stalls. This year there will be more than one hundred and fifty, so you'd better come hungry.","start":13.96,"end":22.05},{"who":"A","text":"It runs from ten in the morning until nine at night on both Saturday and Sunday. Entry is free for everyone this year, because a local bank has agreed to sponsor the event.","start":22.5,"end":32.16},{"who":"A","text":"The organisers strongly recommend that you don't drive. Parking near the harbour is very limited, so take the free shuttle bus from the railway station, which leaves every fifteen minutes.","start":32.61,"end":42.99},{"who":"A","text":"As always, the festival is divided into different areas. Let me tell you what you'll find in each one.","start":43.44,"end":49.54},{"who":"A","text":"In the Market Square, local farmers will be selling fresh fruit, vegetables and cheese. This is the place to stock up for the week.","start":49.99,"end":57.83},{"who":"A","text":"On the Fish Quay, chefs from the town's best restaurants will be giving cooking demonstrations every hour. Seats are limited, so get there early.","start":58.28,"end":66.54},{"who":"A","text":"The Old Warehouse is where you'll find food from around the world, from Mexican tacos to Korean barbecue.","start":66.99,"end":72.42},{"who":"A","text":"Families with young children should head to Castle Gardens, where there will be games and a children's cookery school all weekend.","start":72.87,"end":79.02},{"who":"A","text":"And if you prefer something quieter, the Lighthouse Lawn is the place for live acoustic music while you eat.","start":79.47,"end":84.91},{"who":"A","text":"One new idea this year: the festival is trying to reduce waste, so there will be no plastic plates or cups. Visitors are asked to bring their own water bottles, which can be refilled for free at taps around the site.","start":85.36,"end":97.89},{"who":"A","text":"Finally, a competition. The festival is looking for the best homemade cake in the county. Entries must be brought to the main tent by eleven o'clock on Saturday morning, and the winner will be announced at four.","start":98.34,"end":110.79}],"testId":"t2"},{"n":3,"title":"A presentation on sleep and memory","intro":"Section 3. You will hear two psychology students, Hannah and Sam, planning a presentation on sleep and memory.","speakers":{"A":{"voice":"Karen","name":"Hannah"},"B":{"voice":"Reed","name":"Sam"}},"groups":[{"title":"Questions 21–25","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":21,"type":"mcq","q":"What did Hannah find most useful about the Harvard study?","options":["A  its results","B  the way memory was tested","C  the number of participants"],"answer":"B","key":"the way they tested memory","line":2},{"n":22,"type":"mcq","q":"What weakness of the study do the students mention?","options":["A  The sample was small.","B  The test was too easy.","C  It only tested students."],"answer":"A","key":"the sample was quite small","line":4},{"n":23,"type":"mcq","q":"How will the presentation begin?","options":["A  with a statistic","B  with a question for the audience","C  with a diagram"],"answer":"B","key":"I'd rather start with a question to the audience","line":7},{"n":24,"type":"mcq","q":"According to the tutor, the main focus should be on","options":["A  the stages of sleep.","B  practical advice.","C  research evidence."],"answer":"C","key":"the main focus should be on the research evidence","line":10},{"n":25,"type":"mcq","q":"When will the students rehearse?","options":["A  Wednesday","B  Thursday afternoon","C  Friday morning"],"answer":"B","key":"How about Thursday afternoon","line":20}]},{"title":"Questions 26–30","instruction":"Who will do each task? Choose the correct letter, A, B or C. A = Hannah, B = Sam, C = both of them.","box":["A  Hannah","B  Sam","C  both Hannah and Sam"],"questions":[{"n":26,"type":"match","q":"the introduction","options":["A","B","C"],"answer":"B","key":"Shall I do the introduction and the sleep stages","line":13},{"n":27,"type":"match","q":"the slides","options":["A","B","C"],"answer":"A","key":"could you do them","line":15},{"n":28,"type":"match","q":"the images for the sleep stages","options":["A","B","C"],"answer":"B","key":"if you find the images for the sleep stages","line":16},{"n":29,"type":"match","q":"the handout","options":["A","B","C"],"answer":"B","key":"I'll write the handout","line":17},{"n":30,"type":"match","q":"the practical advice","options":["A","B","C"],"answer":"C","key":"we'll both do the practical advice together","line":18}]}],"audio":"t2-s3.mp3","duration":133,"lines":[{"who":"A","text":"So, Sam, we need to plan our presentation on sleep and memory. It's due next Friday.","start":9.41,"end":15.68},{"who":"B","text":"Right. I've been reading that study by the Harvard team. Did you get a chance to look at it?","start":16.28,"end":22.19},{"who":"A","text":"Yes. What I found most useful was the way they tested memory. They taught people a list of word pairs in the evening, and tested them the next morning.","start":22.79,"end":32.65},{"who":"B","text":"And the people who slept remembered about twenty percent more than the people who stayed awake.","start":33.25,"end":37.42},{"who":"A","text":"Exactly. Although I think the sample was quite small. Only forty students took part.","start":38.02,"end":44.84},{"who":"B","text":"True. We should mention that as a weakness.","start":45.44,"end":48.42},{"who":"A","text":"Now, how should we start the presentation? I thought maybe with a statistic.","start":49.02,"end":54.03},{"who":"B","text":"I'd rather start with a question to the audience. Something like, how many of you slept less than six hours last night?","start":54.63,"end":61.35},{"who":"A","text":"Oh, I like that. It gets people involved straight away.","start":61.95,"end":65.96},{"who":"B","text":"Then we could explain the different stages of sleep. I can draw a simple diagram.","start":66.56,"end":71.52},{"who":"A","text":"Good. But let's not spend too long on that. The tutor said the main focus should be on the research evidence.","start":72.12,"end":79.83},{"who":"B","text":"Agreed. What about the part on practical advice for students?","start":80.43,"end":84.34},{"who":"A","text":"I think that's important, but we should keep it to the end. Two or three tips at the most.","start":84.94,"end":90.66},{"who":"B","text":"OK. Now, who does what? Shall I do the introduction and the sleep stages?","start":91.26,"end":97.22},{"who":"A","text":"Fine. I'll present the Harvard study. And who's doing the slides?","start":97.82,"end":103.13},{"who":"B","text":"You're better at design than me, so could you do them?","start":103.73,"end":106.18},{"who":"A","text":"All right, if you find the images for the sleep stages.","start":106.78,"end":109.99},{"who":"B","text":"Deal. And I'll write the handout for the audience.","start":110.59,"end":113.82},{"who":"A","text":"Great. Then we'll both do the practical advice together, and the questions at the end.","start":114.42,"end":119.96},{"who":"B","text":"When shall we rehearse?","start":120.56,"end":121.63},{"who":"A","text":"Not on Wednesday, I've got a lab session. How about Thursday afternoon in the library group room?","start":122.23,"end":128.63},{"who":"B","text":"Thursday works. I'll book the room.","start":129.23,"end":131.96}],"testId":"t2"},{"n":4,"title":"Restoring coral reefs","intro":"Section 4. You will hear part of a lecture about coral reefs.","speakers":{"A":{"voice":"Daniel","name":"Lecturer"}},"groups":[{"title":"Questions 31–40","instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","questions":[{"n":31,"type":"gap","q":"Reefs are home to about a ______ of marine species","answer":["quarter"],"line":1},{"n":32,"type":"gap","q":"Corals are made up of tiny creatures called ______","answer":["polyps"],"line":2},{"n":33,"type":"gap","q":"Algae give coral its food and its ______","answer":["colour","color"],"line":3},{"n":34,"type":"gap","q":"Bleaching: coral turns ______ when water is too warm","answer":["white"],"line":4},{"n":35,"type":"gap","q":"Other threats: pollution from ______, overfishing, tourists","answer":["farms"],"line":6},{"n":36,"type":"gap","q":"Coral gardening: pieces grown on underwater ______","answer":["frames"],"line":7},{"n":37,"type":"gap","q":"Disadvantage: slow and ______","answer":["expensive"],"line":9},{"n":38,"type":"gap","q":"Recordings of a healthy reef attract ______ back","answer":["fish"],"line":6},{"n":39,"type":"gap","q":"Fish eat the ______ that covers the coral","answer":["seaweed"],"line":11},{"n":40,"type":"gap","q":"Long-term solution: cutting carbon ______","answer":["emissions"],"line":13}]}],"audio":"t2-s4.mp3","duration":111.9,"lines":[{"who":"A","text":"In today's lecture, I want to look at coral reefs, and at what scientists are doing to restore them.","start":6.1,"end":11.16},{"who":"A","text":"Coral reefs cover less than one percent of the ocean floor, yet they are home to around a quarter of all marine species.","start":11.61,"end":17.8},{"who":"A","text":"Although corals look like plants or rocks, they are actually animals. Each coral is made up of thousands of tiny creatures called polyps.","start":18.25,"end":26.3},{"who":"A","text":"Most reef-building corals live with tiny algae inside their bodies. The algae produce food through photosynthesis, and they also give the coral its colour.","start":26.75,"end":35.9},{"who":"A","text":"When the water becomes too warm, the coral pushes the algae out, and turns white. This is called bleaching.","start":36.35,"end":42.91},{"who":"A","text":"A bleached coral is not dead, but it is starving. If the temperature does not fall within a few weeks, it will die.","start":43.36,"end":50.09},{"who":"A","text":"Rising sea temperatures are the main threat, but reefs are also damaged by pollution from farms, by overfishing, and by careless tourists.","start":50.54,"end":58.38},{"who":"A","text":"So what can be done? One method is called coral gardening. Small pieces of healthy coral are grown on underwater frames, a bit like trees in a nursery.","start":58.83,"end":68.68},{"who":"A","text":"After about a year, they are large enough to be planted back onto the damaged reef.","start":69.13,"end":73.1},{"who":"A","text":"This method works well, but it is slow and expensive, so it can only be used on small areas.","start":73.55,"end":78.82},{"who":"A","text":"Another approach uses sound. Researchers in Australia found that playing recordings of a healthy reef through underwater speakers attracted fish back to damaged areas.","start":79.27,"end":88.63},{"who":"A","text":"The fish help the reef recover by eating the seaweed that would otherwise cover the coral.","start":89.08,"end":92.9},{"who":"A","text":"Scientists are also breeding corals that can survive higher temperatures. This is promising, but it raises questions about changing natural ecosystems.","start":93.35,"end":102.33},{"who":"A","text":"In the end, most experts agree that restoration alone is not enough. Without cutting carbon emissions, reefs will continue to decline.","start":102.78,"end":110.88}],"testId":"t2"}]},{"id":"t3","title":"模拟听力 3","sections":[{"n":1,"title":"Reporting lost property","intro":"Section 1. You will hear a woman reporting a lost bag at a railway station.","speakers":{"A":{"voice":"Reed","name":"Officer"},"B":{"voice":"Samantha","name":"Woman"}},"groups":[{"title":"Questions 1–10","instruction":"Complete the form below. Write ONE WORD AND/OR A NUMBER for each answer.","questions":[{"n":1,"type":"gap","q":"Train: the ______ from Manchester","answer":["6.15","six fifteen","6:15"],"line":3},{"n":2,"type":"gap","q":"Colour of bag: dark ______","answer":["green"],"line":5},{"n":3,"type":"gap","q":"Strap made of ______","answer":["leather"],"line":5},{"n":4,"type":"gap","q":"Badge shows a ______","answer":["mountain"],"line":7},{"n":5,"type":"gap","q":"Contents: laptop, blue ______, library book","answer":["umbrella"],"line":9},{"n":6,"type":"gap","q":"Glasses in a ______ case","answer":["red"],"line":13},{"n":7,"type":"gap","q":"Name: Laura ______","answer":["Whitfield"],"line":15},{"n":8,"type":"gap","q":"Bag currently at ______ station","answer":["Northgate"],"line":20},{"n":9,"type":"gap","q":"Expected to arrive by: ______","answer":["Thursday"],"line":20},{"n":10,"type":"gap","q":"Handling fee: £______","answer":["3","three"],"line":17}]}],"audio":"t3-s1.mp3","duration":122.6,"lines":[{"who":"A","text":"Good morning, lost property office. How can I help you?","start":6.85,"end":10.74},{"who":"B","text":"Hi. I left my bag on a train yesterday evening, and I'm hoping someone has handed it in.","start":11.34,"end":16.81},{"who":"A","text":"I'll take some details and check for you. Which train were you on?","start":17.41,"end":21.38},{"who":"B","text":"The six fifteen from Manchester. I got off here at about seven forty.","start":21.98,"end":26.71},{"who":"A","text":"And can you describe the bag?","start":27.31,"end":28.68},{"who":"B","text":"It's a small backpack. Dark green, with a brown leather strap on the top.","start":29.28,"end":34.1},{"who":"A","text":"Any name or label on it?","start":34.7,"end":35.92},{"who":"B","text":"No, but there's a badge on the front pocket. It's a picture of a mountain.","start":36.52,"end":41.04},{"who":"A","text":"OK. And what was inside?","start":41.64,"end":44.07},{"who":"B","text":"My laptop, which is the main thing I'm worried about. Also a blue umbrella and a book.","start":44.67,"end":49.89},{"who":"A","text":"Do you remember the title of the book? It helps us identify things.","start":50.49,"end":54.74},{"who":"B","text":"It's called The Silent Coast. It's a library book, actually, so I really need it back.","start":55.34,"end":60.99},{"who":"A","text":"Was there any money in the bag?","start":61.59,"end":62.92},{"who":"B","text":"Just a few coins. Oh, and my glasses, in a red case.","start":63.52,"end":68.07},{"who":"A","text":"Right. Can I take your name?","start":68.67,"end":71.02},{"who":"B","text":"Yes, it's Laura Whitfield. W-H-I-T-F-I-E-L-D.","start":71.62,"end":75.91},{"who":"A","text":"And a contact number?","start":76.51,"end":77.5},{"who":"B","text":"Zero seven seven one two, four eight three, six two nine.","start":78.1,"end":82.12},{"who":"A","text":"Let me just read that back. Zero seven seven one two, four eight three, six two nine.","start":82.72,"end":88.9},{"who":"B","text":"That's right.","start":89.5,"end":90.16},{"who":"A","text":"Now, I can see that a green backpack was handed in last night, but it's at our other office, at Northgate station. It should arrive here by Thursday.","start":90.76,"end":99.48},{"who":"B","text":"Thursday. That's fine. Do I need to bring anything when I collect it?","start":100.08,"end":105.3},{"who":"A","text":"Yes, please bring some photo identification, like a passport or driving licence. There's also a small handling fee of three pounds.","start":105.9,"end":114.41},{"who":"B","text":"No problem. What time are you open?","start":115.01,"end":117.77},{"who":"A","text":"From eight in the morning until six in the evening, Monday to Saturday.","start":118.37,"end":121.59}],"testId":"t3"},{"n":2,"title":"A guided walk at Fernhill Nature Reserve","intro":"Section 2. You will hear a guide talking to a group of visitors at a nature reserve.","speakers":{"A":{"voice":"Moira","name":"Guide"}},"groups":[{"title":"Questions 11–14","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":11,"type":"mcq","q":"Before it became a reserve, the land was","options":["A  a forest.","B  a farm.","C  a park."],"answer":"B","key":"it was a working farm until nineteen ninety-eight","line":1},{"n":12,"type":"mcq","q":"Why must dogs be kept on a lead?","options":["A  Birds are nesting on the ground.","B  There are sheep on the reserve.","C  The paths are narrow."],"answer":"A","key":"ground-nesting birds are breeding","line":3},{"n":13,"type":"mcq","q":"What will visitors receive at the end of the walk?","options":["A  a map of the reserve","B  a free hot drink","C  a discount on membership"],"answer":"B","key":"a free hot drink with your ticket","line":11},{"n":14,"type":"mcq","q":"The bat walk takes place","options":["A  every Friday.","B  on the first Friday of each month.","C  on the last Friday of each month."],"answer":"B","key":"first Friday of every month","line":12}]},{"title":"Questions 15–20","instruction":"What can visitors see or do at each place on the walk? Choose SIX answers from the box and write the correct letter, A–H.","box":["A  very old trees","B  watch birds","C  see butterflies","D  get drinking water","E  feed farm animals","F  a lake dug by hand","G  buy souvenirs","H  cross a bridge"],"questions":[{"n":15,"type":"match","q":"the old mill","options":["A","B","C","D","E","F","G","H"],"answer":"B","key":"our bird-watching hide","line":6},{"n":16,"type":"match","q":"Oak Wood","options":["A","B","C","D","E","F","G","H"],"answer":"A","key":"over four hundred years old","line":7},{"n":17,"type":"match","q":"the lake","options":["A","B","C","D","E","F","G","H"],"answer":"F","key":"dug by hand in the nineteenth century","line":8},{"n":18,"type":"match","q":"the wildflower meadow","options":["A","B","C","D","E","F","G","H"],"answer":"C","key":"full of butterflies","line":9},{"n":19,"type":"match","q":"the picnic area","options":["A","B","C","D","E","F","G","H"],"answer":"D","key":"toilets and a drinking water tap","line":10},{"n":20,"type":"match","q":"between the mill and Oak Wood","options":["A","B","C","D","E","F","G","H"],"answer":"H","key":"we cross the wooden bridge","line":7}]}],"audio":"t3-s2.mp3","duration":118.7,"lines":[{"who":"A","text":"Hello everyone, and welcome to Fernhill Nature Reserve. I'm Claire, and I'll be leading today's walk.","start":7.15,"end":14.09},{"who":"A","text":"The reserve covers about two hundred hectares, and it was a working farm until nineteen ninety-eight, when a local charity bought the land.","start":14.54,"end":22.48},{"who":"A","text":"Our walk today will take about two hours. The path is mostly flat, but it can be muddy near the lake, so I hope you've all got good boots.","start":22.93,"end":32.43},{"who":"A","text":"Before we start, a few rules. Please keep dogs on a lead at all times, because ground-nesting birds are breeding at this time of year.","start":32.88,"end":41.83},{"who":"A","text":"And please don't pick any flowers. Some of the orchids here are extremely rare.","start":42.28,"end":47.93},{"who":"A","text":"Now, let me explain our route, using the map on this board. We're at the visitor centre, in the south of the reserve.","start":48.38,"end":56.23},{"who":"A","text":"First, we'll walk north along the stream to the old mill. The mill is now our bird-watching hide, and if we're lucky we'll see kingfishers.","start":56.68,"end":65.89},{"who":"A","text":"From the mill, we cross the wooden bridge and go into Oak Wood. This is the oldest part of the reserve. Some of the trees are over four hundred years old.","start":66.34,"end":77.05},{"who":"A","text":"After the wood, we come to the lake. The lake was actually dug by hand in the nineteenth century, to provide water for the farm animals.","start":77.5,"end":86.35},{"who":"A","text":"On the east side of the lake is the wildflower meadow. In June it's full of butterflies, so keep your cameras ready.","start":86.8,"end":94.21},{"who":"A","text":"Then we'll return to the visitor centre past the picnic area, where there are toilets and a drinking water tap.","start":94.66,"end":100.68},{"who":"A","text":"When we get back, the café will be open, and all of you will get a free hot drink with your ticket.","start":101.13,"end":106.56},{"who":"A","text":"If you'd like to come back, our volunteers run a bat walk on the first Friday of every month, starting at sunset. It's very popular, so book in advance.","start":107.01,"end":117.75}],"testId":"t3"},{"n":3,"title":"Discussing a work placement report","intro":"Section 3. You will hear a business student, Nadia, discussing her work placement report with her tutor, Professor Hill.","speakers":{"A":{"voice":"Tessa","name":"Nadia"},"B":{"voice":"Daniel","name":"Professor Hill"}},"groups":[{"title":"Questions 21–24","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":21,"type":"mcq","q":"Where did Nadia do her placement?","options":["A  in a sports centre","B  in the marketing department of a clothing company","C  in the sales department of a bank"],"answer":"B","key":"marketing department of a sports clothing company","line":1},{"n":22,"type":"mcq","q":"What did Nadia find most valuable?","options":["A  working with real customer data","B  meeting senior managers","C  designing a website"],"answer":"A","key":"working with real customer data","line":3},{"n":23,"type":"mcq","q":"How has the placement changed Nadia's career plans?","options":["A  She now wants to work abroad.","B  She would now prefer a smaller business.","C  She now wants to stay in marketing."],"answer":"B","key":"I'd prefer a smaller business","line":15},{"n":24,"type":"mcq","q":"When must Nadia send the next draft?","options":["A  at the end of next week","B  by Monday the 14th","C  on the deadline day"],"answer":"B","key":"Monday the fourteenth","explain":"Nadia 提议下周末，教授改成了 14 号星期一。","line":18}]},{"title":"Questions 25–30","instruction":"What does the tutor say about each part of the report? Choose SIX answers from the box and write the correct letter, A–G.","box":["A  It is too long.","B  It is very clear.","C  It needs more about personal development.","D  Some information is missing.","E  It should be removed.","F  It needs more examples from the company.","G  It shows how her confidence grew."],"questions":[{"n":25,"type":"match","q":"description of the company","options":["A","B","C","D","E","F","G"],"answer":"A","key":"Your description of the company is too long","line":4},{"n":26,"type":"match","q":"social media campaign section","options":["A","B","C","D","E","F","G"],"answer":"B","key":"You explain your decisions very clearly","line":6},{"n":27,"type":"match","q":"reflection","options":["A","B","C","D","E","F","G"],"answer":"C","key":"you don't say what you learned about yourself","line":8},{"n":28,"type":"match","q":"references","options":["A","B","C","D","E","F","G"],"answer":"D","key":"missing the year of publication","line":12},{"n":29,"type":"match","q":"the presentation to managers (what Nadia should add)","options":["A","B","C","D","E","F","G"],"answer":"G","key":"How did that change your confidence","line":10},{"n":30,"type":"match","q":"the company's history","options":["A","B","C","D","E","F","G"],"answer":"E","key":"Focus on what you did, not on the company's history","explain":"教授说写自己做了什么，不要写公司历史，也就是这部分应该删掉。","line":6}]}],"audio":"t3-s3.mp3","duration":138.3,"lines":[{"who":"B","text":"Come in, Nadia. I've read the first draft of your placement report. How did you feel the placement went overall?","start":9.76,"end":17.41},{"who":"A","text":"Really well. I spent ten weeks in the marketing department of a sports clothing company, and I learned a lot more than I expected.","start":18.01,"end":26.01},{"who":"B","text":"What was the most valuable part for you?","start":26.61,"end":28.4},{"who":"A","text":"I think working with real customer data. At university we use made-up examples, but there I had to deal with messy information and decide what was actually important.","start":29,"end":39.47},{"who":"B","text":"That comes across well in the report. Now, I have a few comments. Your description of the company is too long. Two pages is enough; you have five.","start":40.07,"end":50.96},{"who":"A","text":"OK. I wasn't sure how much background to include.","start":51.56,"end":55.31},{"who":"B","text":"Focus on what you did, not on the company's history. The section on the social media campaign, on the other hand, is excellent. You explain your decisions very clearly.","start":55.91,"end":66.52},{"who":"A","text":"Thank you. That was the project I enjoyed most.","start":67.12,"end":70.62},{"who":"B","text":"Where the report is weak is the reflection. You describe what happened, but you don't say what you learned about yourself.","start":71.22,"end":77.55},{"who":"A","text":"I see. So I should write more about my own development?","start":78.15,"end":82.26},{"who":"B","text":"Yes. For example, you mention that you had to give a presentation to the managers. How did that change your confidence?","start":82.86,"end":90.53},{"who":"A","text":"It definitely helped. I was terrified at first, but afterwards they asked me to present again.","start":91.13,"end":97.5},{"who":"B","text":"Then say so. Also, your references need attention. Several of them are missing the year of publication.","start":98.1,"end":105.31},{"who":"A","text":"I'll fix those.","start":105.91,"end":106.91},{"who":"B","text":"Now, let's think about how the placement connects to your future plans. Has it changed what you want to do after graduating?","start":107.51,"end":114.39},{"who":"A","text":"A bit. Before, I wanted to work for a big international company. Now I think I'd prefer a smaller business, where you can see the results of your work more quickly.","start":114.99,"end":125.96},{"who":"B","text":"That's a valuable insight. When can you send me the next draft?","start":126.56,"end":130.39},{"who":"A","text":"Would the end of next week be OK?","start":130.99,"end":132.79},{"who":"B","text":"Let's say Monday the fourteenth, so I have time to read it before the deadline.","start":133.39,"end":137.3}],"testId":"t3"},{"n":4,"title":"Colour psychology in marketing","intro":"Section 4. You will hear part of a lecture about the use of colour in marketing.","speakers":{"A":{"voice":"Karen","name":"Lecturer"}},"groups":[{"title":"Questions 31–40","instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","questions":[{"n":31,"type":"gap","q":"People judge a product within ninety ______","answer":["seconds"],"line":1},{"n":32,"type":"gap","q":"Red: linked with energy and ______","answer":["urgency"],"line":2},{"n":33,"type":"gap","q":"Red may increase ______","answer":["appetite"],"line":3},{"n":34,"type":"gap","q":"Blue: linked with trust; used by banks and ______ companies","answer":["technology"],"line":4},{"n":35,"type":"gap","q":"Green: often used for ______ products","answer":["organic"],"line":6},{"n":36,"type":"gap","q":"In Western countries, white represents ______","answer":["purity"],"line":7},{"n":37,"type":"gap","q":"In parts of East Asia, white is associated with ______","answer":["mourning"],"line":7},{"n":38,"type":"gap","q":"Black packaging suggests elegance and ______","answer":["quality"],"line":9},{"n":39,"type":"gap","q":"Products are noticed more if they have strong ______ with others on the shelf","answer":["contrast"],"line":10},{"n":40,"type":"gap","q":"A poor ______ cannot be saved by colour alone","answer":["product"],"line":1}]}],"audio":"t3-s4.mp3","duration":120,"lines":[{"who":"A","text":"Good morning. Today's topic is colour psychology, and how companies use colour to influence what we buy.","start":6.87,"end":13.86},{"who":"A","text":"Research suggests that people form an opinion about a product within ninety seconds, and that up to ninety percent of that judgement can be based on colour alone.","start":14.31,"end":22.78},{"who":"A","text":"Let's start with red. Red is associated with energy and urgency. That's why it's so often used in sales, with signs saying fifty percent off.","start":23.23,"end":33.54},{"who":"A","text":"Red also seems to increase appetite, which may explain why many fast food chains use it in their logos.","start":33.99,"end":40.36},{"who":"A","text":"Blue, on the other hand, is linked with trust and reliability. It's very popular with banks and technology companies.","start":40.81,"end":48.44},{"who":"A","text":"However, blue is rarely used for food, because there are very few naturally blue foods, and it can reduce appetite.","start":48.89,"end":55.6},{"who":"A","text":"Green is connected with nature and health, so it's often used for organic products. But be careful: in some cultures, green has very different meanings.","start":56.05,"end":65.77},{"who":"A","text":"This brings me to an important point. The meaning of colours is not universal. In many Western countries, white represents purity, and is worn at weddings. In parts of East Asia, white has traditionally been associated with mourning.","start":66.22,"end":82.55},{"who":"A","text":"So international companies must research local culture before they launch a product.","start":83,"end":87.75},{"who":"A","text":"Colour also affects how expensive a product seems. Black packaging is often used for luxury goods, because it suggests elegance and quality.","start":88.2,"end":97.17},{"who":"A","text":"Another interesting finding is about contrast. Products that stand out from those around them on a shelf are more likely to be noticed, even if the colour itself is not very attractive.","start":97.62,"end":108.62},{"who":"A","text":"Finally, it's worth remembering that colour is not the whole story. If the product itself is poor, a clever colour scheme will not keep customers coming back.","start":109.07,"end":119}],"testId":"t3"}]},{"id":"t4","title":"模拟听力 4","sections":[{"n":1,"title":"Enrolling on an evening course","intro":"Section 1. You will hear a man asking about an evening photography course at a college.","speakers":{"A":{"voice":"Shelley","name":"Receptionist"},"B":{"voice":"Rishi","name":"Man"}},"groups":[{"title":"Questions 1–10","instruction":"Complete the notes below. Write ONE WORD AND/OR A NUMBER for each answer.","questions":[{"n":1,"type":"gap","q":"Course: Introduction to ______","answer":["Photography"],"line":1},{"n":2,"type":"gap","q":"Day: ______ evenings, 7–9 pm","answer":["Tuesday","Tuesdays"],"line":4},{"n":3,"type":"gap","q":"Start date: ______ September","answer":["23","23rd","twenty-third"],"line":6},{"n":4,"type":"gap","q":"Number of classes: ______","answer":["10","ten"],"line":6},{"n":5,"type":"gap","q":"Full price: £______","answer":["180","one hundred and eighty"],"line":8},{"n":6,"type":"gap","q":"Camera: college can lend one for a ______","answer":["deposit"],"line":10},{"n":7,"type":"gap","q":"Room: Arts Building, room ______","answer":["14","fourteen"],"line":12},{"n":8,"type":"gap","q":"Teacher's surname: ______","answer":["Barrow"],"line":14},{"n":9,"type":"gap","q":"End of course: an ______ in the café","answer":["exhibition"],"line":16},{"n":10,"type":"gap","q":"Heard about the course from a ______","answer":["friend"],"line":23}]}],"audio":"t4-s1.mp3","duration":123.5,"lines":[{"who":"A","text":"Good evening, Parkside College, adult education department.","start":7.33,"end":11.47},{"who":"B","text":"Hello. I'm calling about your evening courses. I'm interested in photography.","start":12.07,"end":18.54},{"who":"A","text":"Yes, we have two photography courses this term. There's Introduction to Photography, and Advanced Digital Editing.","start":19.14,"end":26.73},{"who":"B","text":"I'm a complete beginner, so it would be the first one.","start":27.33,"end":30.89},{"who":"A","text":"OK. That course runs on Tuesday evenings, from seven until nine.","start":31.49,"end":36.93},{"who":"B","text":"And when does it start?","start":37.53,"end":38.91},{"who":"A","text":"The first class is on the twenty-third of September, and there are ten classes in total.","start":39.51,"end":44.37},{"who":"B","text":"How much does it cost?","start":44.97,"end":46.36},{"who":"A","text":"The full price is one hundred and eighty pounds, but if you're over sixty or a full-time student, it's half price.","start":46.96,"end":53.71},{"who":"B","text":"I'm neither, unfortunately. Do I need my own camera?","start":54.31,"end":58.86},{"who":"A","text":"You can use a smartphone for the first few weeks, but after that you'll need a camera with manual settings. The college can lend you one if you pay a deposit.","start":59.46,"end":68.8},{"who":"B","text":"That's useful. Where are the classes held?","start":69.4,"end":72.8},{"who":"A","text":"In the Arts Building, room fourteen. It's on the ground floor, next to the library.","start":73.4,"end":79.19},{"who":"B","text":"And who's the teacher?","start":79.79,"end":80.88},{"who":"A","text":"It's Simon Barrow. He's a professional wildlife photographer, and the students love him.","start":81.48,"end":87.39},{"who":"B","text":"Sounds great. Is there a lot of homework?","start":87.99,"end":91.48},{"who":"A","text":"Each week there's a small photo project, and at the end of the course there's an exhibition of the students' work in the college café.","start":92.08,"end":99.08},{"who":"B","text":"OK, I'd like to enrol. Can I do that over the phone?","start":99.68,"end":104.08},{"who":"A","text":"Yes. Can I have your name?","start":104.68,"end":107.11},{"who":"B","text":"It's Arjun Mehta. M-E-H-T-A.","start":107.71,"end":110.61},{"who":"A","text":"And an email address?","start":111.21,"end":112.58},{"who":"B","text":"arjun dot mehta at quickmail dot com.","start":113.18,"end":115.93},{"who":"A","text":"Thank you. How did you hear about the course?","start":116.53,"end":119.73},{"who":"B","text":"A friend of mine did it last year.","start":120.33,"end":122.46}],"testId":"t4"},{"n":2,"title":"Staff induction at the Grand Hotel","intro":"Section 2. You will hear the manager of a hotel speaking to new staff on their first day.","speakers":{"A":{"voice":"Daniel","name":"Manager"}},"groups":[{"title":"Questions 11–16","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":11,"type":"mcq","q":"Where should new staff collect their uniform?","options":["A  from reception","B  from the laundry room","C  from the staff room"],"answer":"B","key":"collect your uniform from the laundry room","line":2},{"n":12,"type":"mcq","q":"Which meals are free for staff on working days?","options":["A  breakfast and lunch","B  lunch and dinner","C  all meals"],"answer":"A","key":"Breakfast and lunch are free","line":3},{"n":13,"type":"mcq","q":"Timesheets should be given to","options":["A  the office.","B  the general manager.","C  your supervisor."],"answer":"C","key":"given to your supervisor, not to the office","line":4},{"n":14,"type":"mcq","q":"If staff are ill, they must","options":["A  send a text message.","B  phone the duty manager.","C  email their supervisor."],"answer":"B","key":"phone the duty manager at least two hours before","line":5},{"n":15,"type":"mcq","q":"According to the manager, guests remember most","options":["A  the comfortable rooms.","B  the food.","C  the friendly staff."],"answer":"C","key":"how friendly the staff are","line":6},{"n":16,"type":"mcq","q":"Where is the staff room?","options":["A  in the basement","B  on the ground floor","C  on the first floor"],"answer":"C","key":"the staff room is on the first floor","line":12}]},{"title":"Questions 17–20","instruction":"Which supervisor should staff contact for each thing? Write the correct letter, A–D.","box":["A  Maria","B  James","C  Priya","D  Tom"],"questions":[{"n":17,"type":"match","q":"reporting an accident","options":["A","B","C","D"],"answer":"C","key":"report any accidents to her","line":10},{"n":18,"type":"match","q":"weekend work at weddings","options":["A","B","C","D"],"answer":"D","key":"work at weddings at the weekend","line":11},{"n":19,"type":"match","q":"the daily list of rooms to clean","options":["A","B","C","D"],"answer":"A","key":"she'll give you your list every morning","line":8},{"n":20,"type":"match","q":"wine training","options":["A","B","C","D"],"answer":"B","key":"organises the weekly wine training","line":9}]}],"audio":"t4-s2.mp3","duration":108.3,"lines":[{"who":"A","text":"Good morning, and welcome to the Grand Hotel. I'm David Price, the general manager. I'd like to give you some important information for your first week.","start":7.53,"end":17},{"who":"A","text":"The hotel has one hundred and twenty rooms, and in summer we're usually almost full, so it can get very busy.","start":17.45,"end":23.01},{"who":"A","text":"First, uniforms. You'll collect your uniform from the laundry room in the basement this afternoon. Please don't wear it outside the hotel.","start":23.46,"end":32.76},{"who":"A","text":"Staff meals are served in the staff canteen. Breakfast and lunch are free on the days you work, but you pay a small amount for dinner.","start":33.21,"end":40.71},{"who":"A","text":"Your timesheet must be completed every Friday, and given to your supervisor, not to the office.","start":41.16,"end":46.21},{"who":"A","text":"If you're ill and can't come to work, you must phone the duty manager at least two hours before your shift starts. Sending a text message is not acceptable.","start":46.66,"end":55.49},{"who":"A","text":"Now, the most important thing in this hotel is the guest experience. Our guests often tell us that what they remember most is not the rooms, but how friendly the staff are.","start":55.94,"end":65.48},{"who":"A","text":"So always greet guests with a smile, even when you're busy.","start":65.93,"end":68.98},{"who":"A","text":"Let me introduce the supervisors you'll be working with. Maria is in charge of housekeeping, so if you're cleaning rooms, she'll give you your list every morning.","start":69.43,"end":78.1},{"who":"A","text":"James runs the restaurant and bar. He also organises the weekly wine training, which is optional but very popular.","start":78.55,"end":85.73},{"who":"A","text":"Priya manages reception. She's also our health and safety officer, so report any accidents to her.","start":86.18,"end":92.41},{"who":"A","text":"And Tom looks after the conference rooms. If you'd like to earn extra money, he often needs people to work at weddings at the weekend.","start":92.86,"end":100.04},{"who":"A","text":"Finally, the staff room is on the first floor. There's free tea and coffee, and lockers for your personal belongings.","start":100.49,"end":107.31}],"testId":"t4"},{"n":3,"title":"A case study on plastic packaging","intro":"Section 3. You will hear two environmental science students, Ben and Chloe, discussing a case study on plastic packaging.","speakers":{"A":{"voice":"Reed","name":"Ben"},"B":{"voice":"Moira","name":"Chloe"}},"groups":[{"title":"Questions 21–26","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":21,"type":"mcq","q":"What surprised Ben about the case study?","options":["A  Customers complained a lot.","B  Sales increased.","C  Prices went down."],"answer":"B","key":"sales actually went up","line":2},{"n":22,"type":"mcq","q":"Customers' early complaints were mainly about","options":["A  bread.","B  fruit.","C  vegetables."],"answer":"A","key":"Mainly about the bread","line":3},{"n":23,"type":"mcq","q":"What negative result did the experiment have?","options":["A  more food waste","B  higher costs for staff","C  fewer customers"],"answer":"A","key":"food waste increased by about four percent","line":5},{"n":24,"type":"mcq","q":"Chloe thinks the supermarket's main mistake was","options":["A  removing plastic too quickly.","B  poor planning of storage.","C  not telling customers."],"answer":"B","key":"hadn't planned the storage well enough","line":7},{"n":25,"type":"mcq","q":"Ben also thinks the supermarket should have","options":["A  trained staff better.","B  lowered prices.","C  advertised more."],"answer":"A","key":"they should have trained the staff better","line":8},{"n":26,"type":"mcq","q":"Which case will the students compare it with?","options":["A  a café chain that banned straws","B  a refill shop scheme in Germany","C  a government recycling campaign"],"answer":"B","key":"the refill shop scheme in Germany","explain":"Ben 先提议咖啡店禁用吸管，Chloe 觉得改动太小，最后两人同意比较德国的补充装商店。","line":11}]},{"title":"Questions 27–30","instruction":"What is the main weakness of each source? Choose FOUR answers from the box and write the correct letter, A–F.","box":["A  It may be biased.","B  It is out of date.","C  It contains no figures.","D  It uses a small sample.","E  It is too difficult to understand.","F  It is not available online."],"questions":[{"n":27,"type":"match","q":"government report","options":["A","B","C","D","E","F"],"answer":"B","key":"quite out of date","line":13},{"n":28,"type":"match","q":"newspaper article","options":["A","B","C","D","E","F"],"answer":"C","key":"doesn't give any figures","line":14},{"n":29,"type":"match","q":"supermarket's own report","options":["A","B","C","D","E","F"],"answer":"A","key":"written to make the company look good","line":15},{"n":30,"type":"match","q":"university survey","options":["A","B","C","D","E","F"],"answer":"D","key":"the sample was only two hundred people","line":16}]}],"audio":"t4-s3.mp3","duration":137.6,"lines":[{"who":"A","text":"So Chloe, have you finished reading the case study about the supermarket that removed plastic packaging?","start":9.86,"end":14.94},{"who":"B","text":"Yes. I thought it was really interesting. They removed plastic from all their fruit and vegetables for six months.","start":15.54,"end":23.95},{"who":"A","text":"What surprised me was that sales actually went up. I expected customers to complain.","start":24.55,"end":29.76},{"who":"B","text":"Some did, at first. Mainly about the bread, because it went stale more quickly.","start":30.36,"end":36.14},{"who":"A","text":"Right. And the store had a problem with waste, didn't it? More fruit was thrown away because it got damaged.","start":36.74,"end":43.99},{"who":"B","text":"Yes, food waste increased by about four percent, which is a serious point, because food waste also has a big environmental cost.","start":44.59,"end":52.72},{"who":"A","text":"So do you think the experiment was a success overall?","start":53.32,"end":55.75},{"who":"B","text":"I'd say partly. It showed that customers are willing to change, but the supermarket hadn't planned the storage well enough.","start":56.35,"end":64.16},{"who":"A","text":"I agree. I think they should have trained the staff better, too. Several workers said they didn't know how to handle loose produce.","start":64.76,"end":72.84},{"who":"B","text":"Good point. For our assignment, what should we focus on? We only have two thousand words.","start":73.44,"end":81.09},{"who":"A","text":"I think we should compare it with another case. Maybe the café chain that banned plastic straws.","start":81.69,"end":87.32},{"who":"B","text":"Hmm, that's a much smaller change. I'd prefer to compare it with the refill shop scheme in Germany. That was also about packaging.","start":87.92,"end":97.37},{"who":"A","text":"OK, that makes more sense. Now, let's divide the sources. There are four main ones.","start":97.97,"end":104.54},{"who":"B","text":"The government report has the most reliable data, but it's very long and quite out of date.","start":105.14,"end":110.52},{"who":"A","text":"The newspaper article is short and easy to read, but it doesn't give any figures.","start":111.12,"end":115.15},{"who":"B","text":"Then there's the supermarket's own report. It has lots of figures, but of course it's written to make the company look good.","start":115.75,"end":123.26},{"who":"A","text":"And the university survey of customers is recent and independent, but the sample was only two hundred people.","start":123.86,"end":129.28},{"who":"B","text":"So we need to be careful with all of them. Let's mention those weaknesses in our methodology section.","start":129.88,"end":136.57}],"testId":"t4"},{"n":4,"title":"Ancient water management","intro":"Section 4. You will hear part of a lecture about how ancient societies managed water.","speakers":{"A":{"voice":"Tessa","name":"Lecturer"}},"groups":[{"title":"Questions 31–40","instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","questions":[{"n":31,"type":"gap","q":"Qanat: developed in ancient ______","answer":["Persia"],"line":1},{"n":32,"type":"gap","q":"Water moves by ______ alone, with no pumps","answer":["gravity"],"line":2},{"n":33,"type":"gap","q":"Advantage: little water lost through ______","answer":["evaporation"],"line":3},{"n":34,"type":"gap","q":"Vertical shafts provided ______ for workers","answer":["air"],"line":4},{"n":35,"type":"gap","q":"Stepwells: found mainly in western ______","answer":["India"],"line":6},{"n":36,"type":"gap","q":"Steps let people reach water in every ______","answer":["season","seasons"],"line":7},{"n":37,"type":"gap","q":"Social spaces, especially for ______","answer":["women"],"line":8},{"n":38,"type":"gap","q":"Decorated with ______","answer":["carvings"],"line":8},{"n":39,"type":"gap","q":"Colonial officials thought stepwells were ______","answer":["unhygienic"],"line":10},{"n":40,"type":"gap","q":"Key lesson: the whole ______ shared responsibility","answer":["community"],"line":12}]}],"audio":"t4-s4.mp3","duration":118.9,"lines":[{"who":"A","text":"Today we're going to look at how ancient societies managed water in dry regions, and what we might learn from them.","start":7.52,"end":13.88},{"who":"A","text":"I'll start with the qanat, a system developed in ancient Persia, in what is now Iran, about three thousand years ago.","start":14.33,"end":21.56},{"who":"A","text":"A qanat is an underground tunnel that carries water from a mountain area down to farmland, using gravity alone. No pumps are needed.","start":22.01,"end":30.6},{"who":"A","text":"Because the water travels underground, very little is lost through evaporation, which is a huge advantage in a hot climate.","start":31.05,"end":38.47},{"who":"A","text":"Building a qanat was dangerous work. Workers dug vertical shafts every twenty or thirty metres, which provided air and allowed them to remove the soil.","start":38.92,"end":48.38},{"who":"A","text":"Some qanats are more than fifty kilometres long, and many are still in use today.","start":48.83,"end":53.53},{"who":"A","text":"The second system is the stepwell, found mainly in western India. These are deep wells with stone steps leading down to the water.","start":53.98,"end":62.39},{"who":"A","text":"Because the water level changed with the seasons, the steps allowed people to reach it at any time of year.","start":62.84,"end":68.59},{"who":"A","text":"Stepwells were not only practical. They were also social spaces, especially for women, who met there when they collected water. Many are decorated with beautiful carvings.","start":69.04,"end":80.65},{"who":"A","text":"Inside a stepwell, the temperature can be five or six degrees cooler than outside, so they were also used as places to rest.","start":81.1,"end":88.84},{"who":"A","text":"During the colonial period, many stepwells were closed, because officials believed they were unhygienic, and they were replaced with pipes and taps.","start":89.29,"end":98},{"who":"A","text":"Today, however, some communities are restoring both qanats and stepwells, as they look for ways to cope with water shortages.","start":98.45,"end":106.5},{"who":"A","text":"The key lesson, I think, is that these systems were managed by the whole community. Everyone shared the responsibility for maintenance, and that made them sustainable for centuries.","start":106.95,"end":117.94}],"testId":"t4"}]},{"id":"t5","title":"模拟听力 5","sections":[{"n":1,"title":"Getting a quote from a removal company","intro":"Section 1. You will hear a woman asking a removal company for a quote to move house.","speakers":{"A":{"voice":"Daniel","name":"Company"},"B":{"voice":"Karen","name":"Woman"}},"groups":[{"title":"Questions 1–10","instruction":"Complete the form below. Write ONE WORD AND/OR A NUMBER for each answer.","questions":[{"n":1,"type":"gap","q":"Current address: 28 ______ Avenue, Oxford","answer":["Cedar"],"line":3},{"n":2,"type":"gap","q":"New address: ______ Street, Bristol","answer":["Ashton"],"line":5},{"n":3,"type":"gap","q":"Size of new house: ______ bedrooms","answer":["3","three"],"line":5},{"n":4,"type":"gap","q":"Moving date: Friday ______ October","answer":["4","4th","fourth"],"line":11},{"n":5,"type":"gap","q":"Large item: a ______","answer":["piano"],"line":13},{"n":6,"type":"gap","q":"Number of boxes: about ______","answer":["30","thirty"],"line":15},{"n":7,"type":"gap","q":"Boxes contain mostly books and ______ things","answer":["kitchen"],"line":15},{"n":8,"type":"gap","q":"Boxes delivered one ______ before the move","answer":["week"],"line":18},{"n":9,"type":"gap","q":"Insurance covers up to £______","answer":["20000","20,000","twenty thousand"],"line":20},{"n":10,"type":"gap","q":"Estimated price: £______","answer":["875","eight hundred and seventy-five"],"line":22}]}],"audio":"t5-s1.mp3","duration":122.6,"lines":[{"who":"A","text":"Good morning, Swift Removals. How can I help?","start":7.36,"end":11.03},{"who":"B","text":"Hi. I'm moving house next month, and I'd like a quote for the move.","start":11.63,"end":16.41},{"who":"A","text":"Of course. Where are you moving from?","start":17.01,"end":19.81},{"who":"B","text":"From twenty-eight Cedar Avenue, in Oxford.","start":20.41,"end":22.88},{"who":"A","text":"And where are you moving to?","start":23.48,"end":24.77},{"who":"B","text":"To Bristol. It's a three-bedroom house, in Ashton Street.","start":25.37,"end":29.56},{"who":"A","text":"Is that A-S-H-T-O-N?","start":30.16,"end":31.61},{"who":"B","text":"That's right.","start":32.21,"end":32.99},{"who":"A","text":"And what date are you planning to move?","start":33.59,"end":35.34},{"who":"B","text":"Ideally the fifth of October. It's a Saturday.","start":35.94,"end":39.42},{"who":"A","text":"Saturdays are more expensive, I'm afraid. There's an extra charge of fifty pounds. Would a Friday be possible?","start":40.02,"end":47.62},{"who":"B","text":"Hmm. Actually, yes, Friday the fourth would be fine. I can take the day off work.","start":48.22,"end":54.88},{"who":"A","text":"Great. Now, how much furniture do you have? Are there any very large items?","start":55.48,"end":61.42},{"who":"B","text":"Most things are normal size, but there's a piano. Is that a problem?","start":62.02,"end":66.71},{"who":"A","text":"Not at all, but we'll need to send an extra person. Anything else?","start":67.31,"end":71.61},{"who":"B","text":"There are about thirty boxes, mostly books and kitchen things.","start":72.21,"end":75.82},{"who":"A","text":"Would you like us to do the packing for you? It's an extra service.","start":76.42,"end":80.25},{"who":"B","text":"No, I'll pack everything myself, thanks. But could you provide the boxes?","start":80.85,"end":86.05},{"who":"A","text":"Yes, we can deliver boxes a week before the move. They're free if you book with us.","start":86.65,"end":91.83},{"who":"B","text":"Excellent. And is everything insured?","start":92.43,"end":95.35},{"who":"A","text":"Yes, our standard insurance covers items up to twenty thousand pounds in total. If anything is worth more, you can buy extra cover.","start":95.95,"end":103.94},{"who":"B","text":"That should be enough. So what's the estimated price?","start":104.54,"end":108.36},{"who":"A","text":"For a weekday move with the piano, it would be eight hundred and seventy-five pounds.","start":108.96,"end":113.19},{"who":"B","text":"OK. And how do I confirm the booking?","start":113.79,"end":116.93},{"who":"A","text":"We'll send you the quote by email, and you just need to pay a ten percent deposit.","start":117.53,"end":121.63}],"testId":"t5"},{"n":2,"title":"The new city bike scheme","intro":"Section 2. You will hear a council officer talking about a new bike hire scheme.","speakers":{"A":{"voice":"Tessa","name":"Officer"}},"groups":[{"title":"Questions 11–15","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":11,"type":"mcq","q":"How many bikes will the scheme have at first?","options":["A  40","B  about 400","C  about 800"],"answer":"B","key":"with around four hundred bikes","line":1},{"n":12,"type":"mcq","q":"How can users pay?","options":["A  with cash or card","B  only with a bank card through the app","C  only at the docking station"],"answer":"B","key":"register with a bank card. You can't pay with cash","line":3},{"n":13,"type":"mcq","q":"How much does it cost for members after the first 30 minutes?","options":["A  £1 per extra half hour","B  £1 per extra hour","C  £60 per year only"],"answer":"A","key":"one pound for each extra half hour","line":4},{"n":14,"type":"mcq","q":"Who gets a discount on membership?","options":["A  hospital staff","B  students and people over 65","C  people who live in the old town"],"answer":"B","key":"students and people over sixty-five get a fifty percent discount","line":5},{"n":15,"type":"mcq","q":"Why are helmets not provided?","options":["A  They are too expensive.","B  for hygiene reasons","C  They are not required by law."],"answer":"B","key":"for hygiene reasons","line":7}]},{"title":"Questions 16–20","instruction":"Where will each docking station be? Choose FIVE answers from the box and write the correct letter, A–G.","box":["A  on the top level of the car park","B  by the river bridge","C  next to the sports hall","D  outside the main entrance","E  at the back exit","F  next to the library","G  in the town square"],"questions":[{"n":16,"type":"match","q":"hospital","options":["A","B","C","D","E","F","G"],"answer":"D","key":"outside the main entrance of the hospital","line":9},{"n":17,"type":"match","q":"shopping centre","options":["A","B","C","D","E","F","G"],"answer":"A","key":"in the car park, on the top level","line":10},{"n":18,"type":"match","q":"university","options":["A","B","C","D","E","F","G"],"answer":"C","key":"next to the sports hall, rather than the library","line":11},{"n":19,"type":"match","q":"old town","options":["A","B","C","D","E","F","G"],"answer":"B","key":"by the river bridge","line":12},{"n":20,"type":"match","q":"railway station","options":["A","B","C","D","E","F","G"],"answer":"E","key":"at the back exit, near the taxi rank","line":13}]}],"audio":"t5-s2.mp3","duration":109.8,"lines":[{"who":"A","text":"Good evening, and thank you for coming to this information meeting about the city's new bike hire scheme, which starts on the first of May.","start":6.94,"end":14.21},{"who":"A","text":"There will be forty docking stations across the city at first, with around four hundred bikes. We hope to double that next year.","start":14.66,"end":22.61},{"who":"A","text":"The scheme is designed mainly for short journeys. For example, from the railway station to your office, or from home to the shops.","start":23.06,"end":31.59},{"who":"A","text":"To use the bikes, you'll need to download our app and register with a bank card. You can't pay with cash.","start":32.04,"end":38.69},{"who":"A","text":"The first thirty minutes of every journey are free for members. After that, it costs one pound for each extra half hour.","start":39.14,"end":46.82},{"who":"A","text":"Annual membership costs sixty pounds, but students and people over sixty-five get a fifty percent discount.","start":47.27,"end":53.63},{"who":"A","text":"We've also included a number of electric bikes, which will be especially useful for the hill up to the university.","start":54.08,"end":60.36},{"who":"A","text":"Now, a question we often get is about helmets. Helmets are not provided with the bikes, for hygiene reasons, but we strongly recommend wearing one.","start":60.81,"end":70.67},{"who":"A","text":"Let me tell you where some of the first docking stations will be.","start":71.12,"end":74.09},{"who":"A","text":"There will be a large station outside the main entrance of the hospital, because many staff there work night shifts and don't have easy access to buses.","start":74.54,"end":82.81},{"who":"A","text":"At the shopping centre, the station will be in the car park, on the top level, so it's covered from the rain.","start":83.26,"end":89.65},{"who":"A","text":"The station at the university will be next to the sports hall, rather than the library, because there was more space there.","start":90.1,"end":96.65},{"who":"A","text":"In the old town, the streets are very narrow, so the station will be on the edge, by the river bridge.","start":97.1,"end":103.14},{"who":"A","text":"And at the railway station, the bikes will be at the back exit, near the taxi rank.","start":103.59,"end":108.76}],"testId":"t5"},{"n":3,"title":"A survey on online learning","intro":"Section 3. You will hear two education students, Olivia and Raj, discussing their survey on online learning with their tutor.","speakers":{"A":{"voice":"Samantha","name":"Olivia"},"B":{"voice":"Rishi","name":"Raj"},"C":{"voice":"Karen","name":"Tutor"}},"groups":[{"title":"Questions 21–26","instruction":"Choose the correct letter, A, B or C.","questions":[{"n":21,"type":"mcq","q":"How did most students find the survey?","options":["A  through posters in the canteen","B  through the student union newsletter","C  through their tutors"],"answer":"B","key":"through the student union newsletter","explain":"海报上的二维码 very few people used that，大部分来自学生会通讯。","line":3},{"n":22,"type":"mcq","q":"What did students like most about online classes?","options":["A  saving travel time","B  being able to watch recordings again","C  working in small groups"],"answer":"B","key":"being able to watch recordings again","line":5},{"n":23,"type":"mcq","q":"What was the biggest complaint?","options":["A  poor internet connections","B  too much homework","C  lack of contact with other students"],"answer":"C","key":"lack of contact with other students","line":6},{"n":24,"type":"mcq","q":"Why were science students less positive?","options":["A  They could not do practical work.","B  Their lectures were not recorded.","C  Their classes were too large."],"answer":"A","key":"they couldn't do practical work at home","line":8},{"n":25,"type":"mcq","q":"Language students liked online learning because","options":["A  they could practise with native speakers.","B  they felt less nervous speaking in small groups.","C  the classes were shorter."],"answer":"B","key":"small online groups made them less nervous about speaking","line":9},{"n":26,"type":"mcq","q":"What information did the survey fail to collect?","options":["A  students' year of study","B  students' department","C  students' age"],"answer":"A","key":"we forgot to ask which year of study people were in","line":12}]},{"title":"Questions 27–30","instruction":"Complete the sentences below. Write NO MORE THAN TWO WORDS for each answer.","questions":[{"n":27,"type":"gap","q":"One survey question was badly ______.","answer":["worded"],"line":11},{"n":28,"type":"gap","q":"The university should continue ______ lectures.","answer":["recording"],"line":5},{"n":29,"type":"gap","q":"Online courses should include more ______ to reduce isolation.","answer":["group activities"],"line":15},{"n":30,"type":"gap","q":"Departments will be compared using a ______.","answer":["bar chart"],"line":17}]}],"audio":"t5-s3.mp3","duration":133.8,"lines":[{"who":"C","text":"So, how did the survey on online learning go?","start":10.16,"end":13.05},{"who":"A","text":"Better than we expected. We got responses from just over three hundred students across five departments.","start":13.65,"end":19.64},{"who":"C","text":"That's a good number. How did you collect the responses?","start":20.24,"end":23.97},{"who":"B","text":"We sent the link through the student union newsletter. We also put posters with a QR code in the canteen, but very few people used that.","start":24.57,"end":34.86},{"who":"C","text":"And what were the main findings?","start":35.46,"end":37.14},{"who":"A","text":"The thing most students liked about online classes was being able to watch recordings again. Almost eighty percent mentioned that.","start":37.74,"end":44.94},{"who":"B","text":"The biggest complaint was the lack of contact with other students. Many people said they felt isolated.","start":45.54,"end":53.13},{"who":"C","text":"That matches other research. Was there any difference between departments?","start":53.73,"end":58.71},{"who":"A","text":"Yes. Science students were much less positive, mainly because they couldn't do practical work at home.","start":59.31,"end":65.45},{"who":"B","text":"Whereas students in the language department were surprisingly positive. They said small online groups made them less nervous about speaking.","start":66.05,"end":76.19},{"who":"C","text":"Interesting. Did you find any problems with your survey design?","start":76.79,"end":81.18},{"who":"A","text":"One question was badly worded. We asked whether online learning was 'better or worse', and lots of people wrote that it depended on the subject.","start":81.78,"end":90.04},{"who":"B","text":"And we forgot to ask which year of study people were in, so we can't compare first-year and final-year students.","start":90.64,"end":97.97},{"who":"C","text":"Those are honest points, and you should include them in your discussion. Now, what are your recommendations?","start":98.57,"end":105.04},{"who":"A","text":"We think the university should keep recording lectures, even when classes are back on campus.","start":105.64,"end":110.45},{"who":"B","text":"And online courses should include more group activities, to reduce the feeling of isolation.","start":111.05,"end":117.42},{"who":"C","text":"Good. And how are you going to present the data?","start":118.02,"end":121.28},{"who":"A","text":"We'll use a bar chart to compare the departments, and a pie chart for the overall satisfaction figures.","start":121.88,"end":127.31},{"who":"C","text":"Fine. Just make sure every chart has a clear title and labels.","start":127.91,"end":132.84}],"testId":"t5"},{"n":4,"title":"How birds migrate","intro":"Section 4. You will hear part of a lecture about bird migration.","speakers":{"A":{"voice":"Moira","name":"Lecturer"}},"groups":[{"title":"Questions 31–40","instruction":"Complete the notes below. Write ONE WORD ONLY for each answer.","questions":[{"n":31,"type":"gap","q":"Main reason for migration: ______","answer":["food"],"line":1},{"n":32,"type":"gap","q":"Arctic tern: round trip of about seventy ______ km","answer":["thousand"],"line":0},{"n":33,"type":"gap","q":"Birds use their internal ______ to adjust for time of day","answer":["clock"],"line":4},{"n":34,"type":"gap","q":"Night flyers navigate using the ______","answer":["stars"],"line":5},{"n":35,"type":"gap","q":"Magnetic sense may be located in the ______","answer":["eyes"],"line":6},{"n":36,"type":"gap","q":"Landmarks: coastlines, rivers and ______ ranges","answer":["mountain"],"line":7},{"n":37,"type":"gap","q":"Seabirds may recognise the ______ of their home island","answer":["scent","smell"],"line":8},{"n":38,"type":"gap","q":"Before leaving, birds store extra ______ as fuel","answer":["fat"],"line":9},{"n":39,"type":"gap","q":"Many birds die after hitting ______ buildings","answer":["glass"],"line":10},{"n":40,"type":"gap","q":"Some cities switch off ______ during migration seasons","answer":["lights"],"line":10}]}],"audio":"t5-s4.mp3","duration":132.8,"lines":[{"who":"A","text":"This morning I want to talk about one of the great mysteries of nature: how birds find their way on journeys of thousands of kilometres.","start":6.23,"end":13.95},{"who":"A","text":"Every year, billions of birds migrate between their breeding grounds and the places where they spend the winter. The main reason is food. In winter, insects and plants become scarce in northern regions.","start":14.4,"end":27.69},{"who":"A","text":"The distances can be extraordinary. The Arctic tern travels from the Arctic to the Antarctic and back every year, a round trip of around seventy thousand kilometres.","start":28.14,"end":38.87},{"who":"A","text":"So how do birds navigate? Scientists believe they use several different methods, often together.","start":39.32,"end":46.03},{"who":"A","text":"First, the sun. Birds can tell direction from the position of the sun, and they adjust for the time of day using their internal clock.","start":46.48,"end":55.13},{"who":"A","text":"Birds that fly at night use the stars instead. Experiments in planetariums have shown that young birds learn the pattern of stars around the North Star.","start":55.58,"end":65.5},{"who":"A","text":"Perhaps the most remarkable ability is that birds can detect the Earth's magnetic field. Researchers think this sense may be located in the eyes.","start":65.95,"end":75.33},{"who":"A","text":"Birds also use landmarks, such as coastlines, rivers and mountain ranges, especially near the end of their journey.","start":75.78,"end":83.22},{"who":"A","text":"And there is growing evidence that smell plays a role, particularly for seabirds, which may recognise the scent of their home island.","start":83.67,"end":91.24},{"who":"A","text":"Migration is extremely demanding. Before they leave, many birds eat so much that they almost double their body weight. The extra fat provides fuel for the flight.","start":91.69,"end":103.11},{"who":"A","text":"Unfortunately, migrating birds face many dangers created by humans. Bright city lights confuse birds that fly at night, and many die after hitting glass buildings.","start":103.56,"end":115.18},{"who":"A","text":"Climate change is also a problem, because birds may arrive at their breeding grounds after the insects they depend on have already disappeared.","start":115.63,"end":123.73},{"who":"A","text":"Simple actions can help. Some cities now switch off lights in tall buildings during the main migration seasons.","start":124.18,"end":131.81}],"testId":"t5"}]}]`);export{e as default};
